import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const gradStops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#121218' },
    { at: 1, hex: '#0b0b10' },
  ];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, idxDefault) => {
    const matches = items.filter((i) => i.role === role);
    return matches;
  };

  const group = new Group();
  group.name = 'footer-colophon';

  const BAND_W = 6.8;
  const BAND_H = 2.0;

  // ---- Backdrop / footer band with vertical gradient ----
  const topHex = gradStops[0]?.hex ?? '#121218';
  const botHex = gradStops[gradStops.length - 1]?.hex ?? '#0b0b10';
  const cTop = new Color(topHex);
  const cBot = new Color(botHex);

  const bandMat = new MeshStandardNodeMaterial();
  bandMat.roughness = 0.6;
  bandMat.metalness = 0.2;
  const vGrad = uv().y;
  bandMat.colorNode = mix(
    vec3(cBot.r, cBot.g, cBot.b),
    vec3(cTop.r, cTop.g, cTop.b),
    vGrad
  );

  const band = new Mesh(new PlaneGeometry(BAND_W, BAND_H), bandMat);
  band.position.set(0, 0, -0.02);
  group.add(band);

  // ---- Stage backdrop (larger, behind) to avoid flat void ----
  const stageMat = new MeshBasicNodeMaterial();
  stageMat.colorNode = mix(
    vec3(cBot.r * 0.8, cBot.g * 0.8, cBot.b * 0.8),
    vec3(cTop.r, cTop.g, cTop.b),
    uv().y
  );
  const stage = new Mesh(new PlaneGeometry(7, 3.2), stageMat);
  stage.position.set(0, 0, -0.4);
  group.add(stage);

  // ---- Hairline rules #23232b ----
  const hairColor = new Color('#23232b');
  const hairMat = new MeshBasicNodeMaterial();
  hairMat.colorNode = vec3(hairColor.r * 3.0, hairColor.g * 3.0, hairColor.b * 3.0);

  const topHair = new Mesh(new PlaneGeometry(BAND_W, 0.006), hairMat);
  topHair.position.set(0, BAND_H / 2 - 0.002, 0.01);
  group.add(topHair);

  const legalHair = new Mesh(new PlaneGeometry(BAND_W, 0.006), hairMat);
  legalHair.position.set(0, -BAND_H / 2 + 0.375, 0.01);
  group.add(legalHair);

  // ---- Accent bar beneath wordmark ----
  const accentMat = new MeshStandardNodeMaterial();
  const accentColor = new Color(colors.accent);
  accentMat.color = accentColor;
  accentMat.emissive = accentColor;
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.2;
  const accentBar = new Mesh(new PlaneGeometry(0.3, 0.02), accentMat);
  group.add(accentBar);

  // ---- Layout constants ----
  const leftX = -BAND_W / 2 + 0.25;
  const topY = BAND_H / 2 - 0.35;

  // Wordmark
  const wm = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1,
  });
  wm.position.set(leftX, topY, 0.02);
  group.add(wm);

  accentBar.position.set(leftX + 0.15, topY - 0.28, 0.02);

  // ---- Link columns ----
  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
      to: ['hub-features', 'hub-collection', 'hub-pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
      to: ['hub-journal', null, null],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
      to: [null, null, null],
    },
  ];

  const colStartX = leftX + 2.2;
  const colWidth = 1.2;
  const gutter = 0.375;
  const linkMeshes = [];

  columns.forEach((col, ci) => {
    const cx = colStartX + ci * (colWidth + gutter);
    const header = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#9aa0aa',
      align: 'left',
      letterSpacingPx: 1.1,
    });
    header.position.set(cx, topY, 0.02);
    group.add(header);

    col.links.forEach((lk, li) => {
      const y = topY - 0.28 - li * 0.24;
      const t = ctx.fontAtlas.createText(lk, {
        fontSize: 13,
        color: colors.paper,
        align: 'left',
      });
      t.position.set(cx, y, 0.02);
      group.add(t);
      linkMeshes.push({ mesh: t, to: col.to[li] });
    });
  });

  // ---- Legal line ----
  const legal = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: '#9aa0aa',
      align: 'left',
      letterSpacingPx: 0.4,
    }
  );
  legal.position.set(leftX, -BAND_H / 2 + 0.16, 0.02);
  group.add(legal);

  // ---- Rim / key light grazing upper-left ----
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(-3, 3, 4);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent).getHex(), 0.6);
  rim.position.set(3, -2, 3);
  group.add(rim);

  // ---- Mount animation: fade-up whole band ----
  group.position.y = -0.2;
  const tl = gsap.timeline();
  tl.to(group.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);

  // Fade via traversing materials opacity
  const fadeMats = [];
  group.traverse((o) => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = 0;
      fadeMats.push(o.material);
    }
  });
  fadeMats.forEach((m) => {
    tl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });

  // ---- Hover handlers on links ----
  const hoverTweens = [];
  group.userData.handlers = {
    hover: (payload) => {
      const obj = payload?.object;
      const hit = linkMeshes.find((l) => l.mesh === obj || (obj && obj.parent === l.mesh));
      if (hit) {
        gsap.to(hit.mesh.position, { z: 0.04, duration: 0.14, ease: 'power2.out' });
      }
    },
    hoverout: (payload) => {
      const obj = payload?.object;
      const hit = linkMeshes.find((l) => l.mesh === obj || (obj && obj.parent === l.mesh));
      if (hit) {
        gsap.to(hit.mesh.position, { z: 0.02, duration: 0.14, ease: 'power2.out' });
      }
    },
    click: (payload) => {
      const obj = payload?.object;
      const hit = linkMeshes.find((l) => l.mesh === obj || (obj && obj.parent === l.mesh));
      if (hit && hit.to) {
        ctx.emit('navigate', { to: hit.to });
      }
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    hoverTweens.forEach((t) => t.kill());
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return group;
}
